        {
          "format":"com.atay.iz.backup", "version":5, "exportedAt":6000,
          "journeys":[{"id":"run","title":"Saved run","transport":"RUN","status":"CONFIRMED","startedAt":1000,"endedAt":5000,"expiresAt":null,"note":"Private route","interrupted":false,"stepCount":42}],
          "points":[{"id":"point","journeyId":"run","latitude":41.0,"longitude":29.0,"recordedAt":2000,"accuracy":5.0,"speed":2.0,"altitude":10.0,"breakBefore":true}],
