          "visits":[{"id":"visit","placeId":"place","journeyId":"run","visitedAt":3000,"note":"Private review","rating":4}],
          "photos":[{"id":"photo","relativePath":"photos/old.jpg","journeyId":"run","visitId":"visit","takenAt":3000,"latitude":41.0,"longitude":29.0,"caption":"Saved photo"}],
          "drafts":[{"id":"review","visitId":"visit","text":"Saved review","rating":4,"photoIds":["photo"],"markedSharedAt":null}],
